source:
(()=>{
/* Bài 2 — Biến và lệnh cin (chuẩn mới 19/10/2026)
   Bối cảnh: máy tính tiền của quầy trà sữa lớp mình tại Lễ hội Mùa Xuân.
   Tiết 1 = Chặng 1 (biến, phép gán, phép tính), tiết 2 = Chặng 2 (cin, Nhập → Xử lý → Xuất) và Chặng chứng chỉ.
   Mỗi chặng 6 tab (xem _Nguon_ChuanMoi/VAN_PHONG.md): Bối cảnh → Đoán rồi chạy → Kiểm chứng → Ghi nhớ → Luyện tập → Phản tư.
   Màn hình có số nhập: web và Programiz hiện lại số nhập sau câu dẫn rồi xuống dòng.
*/
"use strict";

const { cuPhap, scratch, tenBien } = window.KIT;
const strip = code => window.CPP.stripComments(code);

/* ---------- đoạn code dùng xuyên suốt ---------- */
// Chặng 1: máy tính tiền nhớ số ly, giá một ly, rồi tính tổng.
const TIEN = `#include <iostream>
using namespace std;
int main() {
    int soLy = 2;
    int giaLy = 25000;
    int tongTien = soLy * giaLy;
    cout << "So ly: " << soLy << endl;
    cout << "Tong tien: " << tongTien;
    return 0;
}`;
// Bản 2 chỉ khác dòng 8: tên biến bị đặt trong " ".
const TIEN_NHAY = TIEN.replace('cout << "Tong tien: " << tongTien;', 'cout << "Tong tien: " << "tongTien";');
const MAN_TIEN = ["So ly: 2\nTong tien: 50000", "So ly: soLy\nTong tien: tongTien", "So ly: 2\nTong tien: tongTien"];
// Gán lại: giảm giá 5000.
const GIAM = `#include <iostream>
using namespace std;
int main() {
    int tongTien = 50000;
    tongTien = tongTien - 5000;
    cout << "Phai tra: " << tongTien;
    return 0;
}`;
const MAN_GIAM = ["Phai tra: 45000", "Phai tra: 50000", "Phai tra: tongTien - 5000"];
const TRA_DAO_LOI = `#include <iostream>
using namespace std;
int main() {
    int soLy = 3;
    int giaLy = 20000;
    int tongTien = soLy + giaLy;
    cout << "So ly: " << soLy << endl;
    cout << "Tong tien: " << "tongTien";
    return 0;
}`;

// Chặng 2: khách tự nhập số ly.
const NHAP = `#include <iostream>
using namespace std;
int main() {
    int soLy;
    cout << "Nhap so ly: ";
    cin >> soLy;
    int tongTien = soLy * 25000;
    cout << "Tong tien: " << tongTien;
    return 0;
}`;
const manNhap = n => `Nhap so ly: ${n}\nTong tien: ${n * 25000}`;
const luaChonNhap = n => [manNhap(n), `Tong tien: ${n * 25000}`, `Nhap so ly: ${n}\nTong tien: soLy * 25000`];
const runNhap = n => ({
  steps: [[4, "", "khai báo soLy"], [5, "Nhap so ly: ", "câu dẫn"], [6, `${n}\n`, `soLy = ${n}`],
    [7, "", `tongTien = ${n} * 25000`], [8, `Tong tien: ${n * 25000}`], [9, "", "kết thúc"]]
});
const KHONG_DAN = `#include <iostream>
using namespace std;
int main() {
    int soLy;
    cin >> soLy;
    int tongTien = soLy * 25000;
    cout << "Tong tien: " << tongTien;
    return 0;
}`;
const CIN_LOI = `#include <iostream>
using namespace std;
int main() {
    int soLy;
    cout << "Nhap so ly: ";
    cin << soLy;
    cout << "Tong tien: " << soLy * 25000;
    return 0;
}`;
const TRA_DAO_KHUNG = `#include <iostream>
using namespace std;
int main() {
    int soLy;
    // 1. In cau dan "Nhap so ly: " roi nhap soLy

    // 2. Tinh tongTien = soLy * 20000

    // 3. In "Tong tien: " va tongTien

    return 0;
}`;
const HOA_DON_KHUNG = `#include <iostream>
using namespace std;
int main() {
    int soLy, soTopping;
    cout << "Nhap so ly: ";
    cin >> soLy;
    cout << "Nhap so topping: ";
    cin >> soTopping;
    // Tinh va in tong tien o day

    return 0;
}`;
const CHIA_KHUNG = `#include <iostream>
using namespace std;
int main() {
    int tongTien, soNguoi;
    cout << "Nhap tong tien: ";
    cin >> tongTien;
    cout << "Nhap so nguoi: ";
    cin >> soNguoi;
    // Tinh tien moi nguoi va so tien con du

    return 0;
}`;

const boiCanh = (big, text) => `<div class="scene-card"><div class="scene-big">${big}</div><p>${text}</p></div>`;
const sauTab = `<div class="mission-row" style="grid-template-columns:repeat(auto-fit,minmax(96px,1fr))">
  ${["Bối cảnh", "Đoán rồi chạy", "Kiểm chứng", "Ghi nhớ", "Luyện tập", "Phản tư"].map((t, i) => `<div>${i + 1}<small>${t}</small></div>`).join("")}</div>`;
const bonBuoc = `<ol class="think-steps">
  <li><strong>Hiểu đề:</strong> nhập gì, tính gì, in gì?</li>
  <li><strong>Chọn biến:</strong> tên biến, kiểu <code>int</code>, ý nghĩa.</li>
  <li><strong>Thiết kế test case trước khi viết:</strong> chọn vài số, tính tay màn hình mong đợi.</li>
  <li><strong>Viết → Chạy → So sánh → Sửa</strong> với từng test case.</li></ol>`;
const tuCham = "Chọn mức đúng với mình. Thầy dùng phần này để biết cần giảng thêm chỗ nào.";
const bangPhepTinh = `<table class="test-table"><tr><th>Phép tính</th><th>Nghĩa là</th><th>Ví dụ</th><th>Kết quả</th></tr>
  <tr><td><code>+</code></td><td>cộng</td><td><code>7 + 2</code></td><td>9</td></tr>
  <tr><td><code>-</code></td><td>trừ</td><td><code>7 - 2</code></td><td>5</td></tr>
  <tr><td><code>*</code></td><td>nhân</td><td><code>7 * 2</code></td><td>14</td></tr>
  <tr><td><code>/</code></td><td>chia, với số nguyên thì <strong>bỏ phần lẻ</strong></td><td><code>7 / 2</code></td><td>3</td></tr>
  <tr><td><code>%</code></td><td>chia lấy <strong>số dư</strong></td><td><code>7 % 2</code></td><td>1</td></tr></table>`;
const luuYCin = `<div class="note-card using-note"><strong>⚠️ Ba lỗi hay gặp với cin</strong>
  <p>1. <strong>Viết ngược mũi tên:</strong> <code>cin &lt;&lt; soLy;</code> là sai. Nhập dùng <code>&gt;&gt;</code>: dữ liệu chảy <em>vào</em> biến.<br>
  2. <strong>Chưa khai báo biến</strong> trước khi <code>cin</code>: máy báo không biết tên biến.<br>
  3. <strong>Quên câu dẫn:</strong> chương trình vẫn chạy, nhưng người dùng không biết phải gõ gì.</p></div>`;
const doanNhap = (id, lan, n, after, whyRight, why) => ({
  id, type: "doanchay", predict: true, showCode: true, icon: "🔮", after,
  title: `Lần ${lan} · Khách gõ ${n}`, prompt: `Khách gõ <code>${n}</code> rồi bấm Enter. Máy sẽ in gì?`,
  code: NHAP, focus: [5, 6], input: String(n), options: luaChonNhap(n), answer: manNhap(n), run: runNhap(n), whyRight, why });

window.LESSON = {
  id: "bai02",
  number: 2,
  title: "Biến và lệnh cin",
  story: "Máy tính tiền của quầy trà sữa",
  badge: { icon: "🧮", name: "Người giữ máy tính tiền" },
  skills: ["Khai báo biến int", "Phép gán", "Phép tính + - * / %", "Đặt tên biến", "Lệnh cin", "Nhập → Xử lý → Xuất"],
  certNote: "Nộp kèm: ảnh bài làm nhóm và bài cá nhân trên Programiz",

  errorTable: [
    ["Màn hình in ra tên biến thay vì số", "Đặt tên biến trong <code>\" \"</code>: <code>cout &lt;&lt; \"tongTien\";</code>", "Bỏ dấu <code>\" \"</code>: <code>cout &lt;&lt; tongTien;</code>"],
    ["Máy không biết tên biến", "Chưa khai báo, hoặc viết sai chữ hoa/thường", "Khai báo trước: <code>int soLy;</code>; gõ đúng tên"],
    ["Lỗi ở dòng cin", "Viết ngược mũi tên <code>cin &lt;&lt;</code>", "Nhập dùng <code>cin &gt;&gt; tenBien;</code>"],
    ["7 / 2 ra 3 chứ không phải 3.5", "Chia hai số nguyên thì bỏ phần lẻ", "Muốn lấy số dư thì dùng <code>%</code>"],
    ["Người dùng không biết gõ gì", "Thiếu câu dẫn trước <code>cin</code>", "In câu dẫn bằng <code>cout</code> ngay trước <code>cin</code>"],
    ["Máy không biết tên \"cout\"", "Thiếu <code>using namespace std;</code>", "Thêm ngay sau <code>#include &lt;iostream&gt;</code>"]
  ],

  steps: [
    /* ================= CHẶNG 1 · TIẾT 1 · biến và phép tính ================= */
    {
      kind: "stage", id: "stage-1", number: 1, nav: "Chặng 1",
      kicker: "CHẶNG 1 · TIẾT 1 · BIẾN, PHÉP GÁN VÀ PHÉP TÍNH",
      title: "Máy tính tiền biết nhớ số",
      bit: "Chào bạn! Mỗi tab là một phần. Làm xong thì bấm <strong>Tiếp</strong> ở cuối trang.",
      objectives: ["Khai báo biến int và gán giá trị cho biến", "Tính tiền bằng phép tính, rồi in giá trị của biến", "Phân biệt in tên biến trong \" \" và in giá trị của biến"],
      flow: [
        { label: "Bối cảnh", title: "Máy tính tiền cần nhớ số ly và giá tiền",
          html: boiCanh("Mỗi ly trà sữa giá 25000 đồng. Khách mua 2 ly.",
            "Máy tính tiền phải <strong>nhớ</strong> số ly, giá một ly, rồi tính tổng tiền. Chỗ để máy nhớ một số gọi là <strong>biến</strong>.") + sauTab },
        { label: "Đoán rồi chạy", title: "Đoán trước, rồi chạy để kiểm tra", tasks: ["c1-dc1", "c1-dc2", "c1-dc3"],
          html: `<p>Có ba chương trình nhỏ. Mỗi lần: <strong>đọc code</strong> → <strong>chọn</strong> màn hình bạn đoán → bấm <strong>▶ Chạy thử</strong>.</p>
            <p>Đoán sai cũng không sao, chạy xong bạn sẽ biết!</p>` },
        { label: "Kiểm chứng", title: "Biến cất gì, máy in gì?", tasks: ["c1-dong4", "c1-chubien", "c1-ten"],
          code: TIEN, focus: [4, 6],
          html: `<p>Nhìn chương trình bên trái. Trả lời theo số dòng.</p>` },
        { label: "Ghi nhớ", title: "Khai báo biến, phép gán và phép tính",
          html: cuPhap({ ten: "KHAI BÁO BIẾN", mau: ["‹kiểu› ‹tên biến›;", "‹kiểu› ‹tên biến› = ‹giá trị›;"],
            phan: [["int", "kiểu <strong>số nguyên</strong> (không có phần lẻ)"], ["‹tên biến›", "tên do bạn đặt, viết liền, không dấu"], ["=", "<strong>phép gán</strong>: cất giá trị bên phải vào biến bên trái"]],
            quyTac: ["Khai báo biến <strong>trước</strong> khi dùng.", "Gán lại được: <code>tongTien = tongTien - 5000;</code> tính vế phải trước rồi cất vào biến.", "In giá trị của biến: <code>cout &lt;&lt; tongTien;</code> — <strong>không</strong> có dấu <code>\" \"</code>."],
            viDu: `int soLy = 2;\nint tongTien = soLy * 25000;\ncout << "Tong tien: " << tongTien;`, man: "Tong tien: 50000" })
            + bangPhepTinh + tenBien()
            + scratch("set [so ly] to (2)\nsay (join [Tong tien: ] ((so ly) * (25000)))", "Giống khối <em>đặt … thành</em> trong Scratch.") },
        { label: "Luyện tập", title: "Điền, rồi sửa hoá đơn trà đào", tasks: ["c1-dien", "c1-sua"],
          html: `<p>Làm theo <strong>4 bước của lập trình viên</strong>:</p>${bonBuoc}` },
        { label: "Phản tư", title: "Bạn đã chắc đến đâu?", tasks: ["c1-tucham"], stop: true,
          html: `<p>${tuCham}</p>`, bit: "Xong Chặng 1! Dừng lại và nhìn lên bảng." }
      ],
      challenges: [
        { id: "c1-dc1", type: "doanchay", predict: true, showCode: true, icon: "🔮",
          title: "Lần 1 · Tính tiền 2 ly", prompt: "Đọc chương trình. Máy sẽ in gì?",
          code: TIEN, focus: [6], options: MAN_TIEN, answer: MAN_TIEN[0],
          run: { steps: [[4, "", "soLy = 2"], [5, "", "giaLy = 25000"], [6, "", "tongTien = 2 * 25000 = 50000"],
            [7, "So ly: 2\n"], [8, "Tong tien: 50000"], [9, "", "kết thúc"]] },
          whyRight: "Biến không có dấu \" \" nên máy in giá trị đang cất trong biến.",
          why: "soLy và tongTien không nằm trong \" \", nên máy in giá trị của biến: 2 và 50000." },
        { id: "c1-dc2", type: "doanchay", predict: true, showCode: true, icon: "🔮", after: "c1-dc1",
          title: "Lần 2 · Chỉ khác dòng 8", prompt: "Dòng 8 đặt tongTien trong dấu \" \". Máy sẽ in gì?",
          code: TIEN_NHAY, focus: [8], options: MAN_TIEN, answer: MAN_TIEN[2],
          run: { steps: [[4, "", "soLy = 2"], [5, "", "giaLy = 25000"], [6, "", "tongTien = 50000"],
            [7, "So ly: 2\n"], [8, "Tong tien: tongTien", "chữ trong \" \""], [9, "", "kết thúc"]] },
          whyRight: "Trong \" \" là chữ, nên máy in nguyên chữ tongTien.",
          why: "Dòng 8 để tongTien trong \" \", nên máy coi đó là chữ và in nguyên chữ tongTien." },
        { id: "c1-dc3", type: "doanchay", predict: true, showCode: true, icon: "🔮", after: "c1-dc2",
          title: "Lần 3 · Giảm giá 5000", prompt: "Dòng 5 gán lại giá trị cho tongTien. Máy sẽ in gì?",
          code: GIAM, focus: [5], options: MAN_GIAM, answer: MAN_GIAM[0],
          run: { steps: [[4, "", "tongTien = 50000"], [5, "", "50000 - 5000 = 45000"], [6, "Phai tra: 45000"], [7, "", "kết thúc"]] },
          whyRight: "Dòng 5 tính 50000 - 5000 rồi cất 45000 vào tongTien.",
          why: "Dòng 5 tính vế phải trước (50000 - 5000 = 45000), rồi cất kết quả vào tongTien. Giá trị cũ bị thay." },
        { id: "c1-dong4", type: "choice", icon: "🔍", title: "Dòng 4 làm gì?",
          prompt: "Dòng 4 viết <code>int soLy = 2;</code>. Dòng này làm gì?",
          options: [
            { text: "Khai báo biến soLy kiểu số nguyên và gán giá trị 2" },
            { text: "In số 2 ra màn hình", why: "Dòng 4 không có cout. Màn hình chỉ có chữ ở dòng 7 và 8." },
            { text: "So sánh soLy với 2", why: "Một dấu = là phép gán. Bài 3 mới học phép so sánh ==." }
          ],
          answer: "Khai báo biến soLy kiểu số nguyên và gán giá trị 2", why: "Đúng. int là kiểu số nguyên; dấu = cất số 2 vào biến soLy." },
        { id: "c1-chubien", type: "truefalse", icon: "✅", title: "Chữ hay giá trị của biến?",
          prompt: "Chọn Đúng hoặc Sai cho từng câu.",
          items: [
            { text: "<code>cout &lt;&lt; soLy;</code> in số 2.", answer: true },
            { text: "<code>cout &lt;&lt; \"soLy\";</code> in số 2.", answer: false, why: "Trong \" \" là chữ: máy in nguyên chữ soLy." },
            { text: "Dòng 6: máy tính 2 * 25000 rồi cất 50000 vào tongTien.", answer: true },
            { text: "Sau lệnh <code>tongTien = tongTien - 5000;</code> ở Lần 3, tongTien vẫn là 50000.", answer: false, why: "Phép gán thay giá trị cũ bằng giá trị mới: 45000." }
          ] },
        { id: "c1-ten", type: "truefalse", icon: "🏷️", title: "Tên biến nào hợp lệ?",
          prompt: "Chọn Đúng nếu tên biến hợp lệ trong C++.",
          items: [
            { text: "<code>tongTien</code>", answer: true },
            { text: "<code>2ly</code>", answer: false, why: "Tên biến không được bắt đầu bằng chữ số." },
            { text: "<code>so ly</code>", answer: false, why: "Tên biến không có dấu cách." },
            { text: "<code>int</code>", answer: false, why: "int là từ khoá của C++, không dùng làm tên biến." }
          ] },
        { id: "c1-dien", type: "fill", icon: "✏️", title: "Điền vào chỗ trống",
          prompt: "Khách mua 3 ly trà đào, mỗi ly 20000 đồng. Điền để máy in đúng <code>Tong tien: 60000</code>.",
          template: `int soLy = 3;\nint giaLy = 20000;\nint tongTien = soLy [[0]] giaLy;\ncout << "Tong tien: " << [[1]];`,
          blanks: [
            { answers: ["*"], options: ["+", "-", "*", "/"], why: "Tiền = số ly nhân giá một ly." },
            { answers: ["tongTien"], options: ["tongTien", "\"tongTien\"", "giaLy"], why: "In giá trị của biến thì không đặt trong \" \"." }
          ],
          screen: "Tong tien: 60000" },
        { id: "c1-sua", type: "code", icon: "🛠️", title: "Sửa hoá đơn trà đào",
          prompt: "Máy in sai tổng tiền. Sửa 2 lỗi để in đúng màn hình mong đợi.",
          card: {
            boiCanh: "Khách mua 3 ly trà đào, mỗi ly 20000 đồng. Máy đang in sai dòng tổng tiền.",
            bien: [["int soLy = 3;", "int", "số ly khách mua"], ["int giaLy = 20000;", "int", "giá một ly (đồng)"], ["int tongTien", "int", "tổng tiền phải trả"]],
            nhap: "Không nhập: các giá trị đã gán sẵn.",
            xuLy: "Dòng 6: tổng tiền = số ly <strong>nhân</strong> giá một ly. Dòng 8: in <strong>giá trị</strong> của tongTien.",
            xuat: "Hai dòng: <code>So ly: 3</code> rồi <code>Tong tien: 60000</code>.",
            tests: [{ input: "", expected: "So ly: 3\nTong tien: 60000", why: "chạy 1 lần, so từng dòng" }],
            dat: "Giống hệt màn hình mong đợi; chỉ ra được 2 dòng đã sửa."
          },
          starter: TRA_DAO_LOI,
          bugs: [
            { label: "Phép tính sai (+ thay vì *)", fixed: code => /soLy\s*\*\s*giaLy|giaLy\s*\*\s*soLy/.test(strip(code)) },
            { label: "Tên biến nằm trong \" \"", fixed: code => !/"tongTien"/.test(strip(code)) }
          ],
          hints: ["3 ly, mỗi ly 20000: phép tính nào cho ra 60000?", "Dòng 6 đổi + thành *. Dòng 8 bỏ dấu \" \" quanh tongTien."] },
        { id: "c1-tucham", type: "self", icon: "🪞", title: "Phản tư Chặng 1",
          prompt: "Mỗi câu chọn một mức.",
          items: ["Mình khai báo được biến int và gán giá trị cho biến.", "Mình biết in giá trị của biến (không dùng dấu \" \").", "Mình đặt được tên biến hợp lệ."] }
      ]
    },

    /* ================= CHẶNG 2 · TIẾT 2 · cin ================= */
    {
      kind: "stage", id: "stage-2", number: 2, nav: "Chặng 2",
      kicker: "CHẶNG 2 · TIẾT 2 · LỆNH cin VÀ NHẬP → XỬ LÝ → XUẤT",
      title: "Khách tự nhập số ly",
      bit: "Chặng này máy hỏi, khách trả lời. Làm lần lượt từng tab nhé.",
      objectives: ["Dùng cin >> để nhập số vào biến", "In câu dẫn trước mỗi lệnh cin", "Viết chương trình theo thứ tự Nhập → Xử lý → Xuất"],
